param([string]$Root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path)
$ErrorActionPreference='Stop';$p=Join-Path $Root 'packages/contracts/openapi/v1.openapi.json';$s=Get-Content $p -Raw|ConvertFrom-Json
$fields=@{issueOtp=@('phone');verifyOtp=@('phone','verificationCode');createEmployee=@('phone','employeeRole');registerVehicle=@('plateNumber','vehicleType');createRouteVersion=@('routeId','stops');queueCheckIn=@('vehicleId','driverId');queueLeave=@('reason');recordGpsObservation=@('entityId','observedAt','latitude','longitude');holdSeat=@('tripId','originStopId','destinationStopId');confirmBooking=@('paymentReference');cancelBooking=@('reason');acceptTaxiOffer=@('driverId');activateStreetQr=@('destination');finishTaxiTrip=@('completedAt');publishPriceVersion=@('pricingScope','effectiveAt');walletPayment=@('amount','paymentReference');requestWithdrawal=@('amount');approveWithdrawal=@('decision');submitComplaint=@('subjectType','subjectId','category');recordComplianceDecision=@('decision');registerEvidence=@('evidenceReference','contentHash');recordEmployeeSignal=@('employeeId','signalType');completeTask=@('completedAt')}
foreach($pathProp in $s.paths.psobject.Properties){foreach($methodProp in $pathProp.Value.psobject.Properties){$op=$methodProp.Value;$id=$op.operationId;$path=$pathProp.Name;if($path -match '\{([^}]+)\}'){$params=@();[regex]::Matches($path,'\{([^}]+)\}')|%{$params+=@{name=$_.Groups[1].Value;in='path';required=$true;schema=@{type='string'}}};$op|Add-Member NoteProperty parameters $params -Force};if($fields.ContainsKey($id)){$schemaName="$id`Request";$props=@{};foreach($f in $fields[$id]){$props[$f]=@{type=if($f -in @('latitude','longitude','amount')){'number'}elseif($f -eq 'stops'){'array'}else{'string'}}};$s.components.schemas|Add-Member NoteProperty $schemaName ([pscustomobject]@{type='object';additionalProperties=$false;required=$fields[$id];properties=$props}) -Force;$op.requestBody.content.'application/json'.schema=@{'$ref'="#/components/schemas/$schemaName"}}}}
[IO.File]::WriteAllText($p,($s|ConvertTo-Json -Depth 50),(New-Object Text.UTF8Encoding($false)))
